// One API call per unique query. Repeat CSV rows are dropped here, not paid for.
function clean(value) {
  return String(value === null || value === undefined ? '' : value).trim();
}

const seen = {};
const out = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const j = items[i].json;
  const row = {
    FNAME: clean(j.FNAME), MNAME: clean(j.MNAME), LNAME: clean(j.LNAME),
    CO_NAME: clean(j.CO_NAME), ADDRESS: clean(j.ADDRESS), CITY: clean(j.CITY),
    COUNTY: clean(j.COUNTY), STATE: clean(j.STATE).toUpperCase(), ZIP: clean(j.ZIP),
    PHONE: clean(j.PHONE), E_MAIL: clean(j.E_MAIL).toLowerCase(),
    DOB: clean(j.DOB), AGE: clean(j.AGE),
  };

  const key = Object.keys(row).map((k) => row[k]).join('|').toUpperCase();
  if (seen[key]) continue;
  seen[key] = true;

  row.search_id = String(out.length + 1);
  row.searched_name = [row.FNAME, row.MNAME, row.LNAME].filter(Boolean).join(' ') || row.CO_NAME;
  row.searched_city = row.CITY;
  row.searched_state = row.STATE;
  row.searched_phone = row.PHONE;
  row.searched_email = row.E_MAIL;

  out.push({ json: row, pairedItem: { item: i } });
}

return out;

// Searchbug collapses a one-item list into a bare object, so every list here
// goes through toArray before it is read. Nothing is truncated to [0].
function toArray(value) {
  if (value === null || value === undefined) return [];
  return Array.isArray(value) ? value : [value];
}

function safe(value) {
  if (value === null || value === undefined) return '';
  if (typeof value === 'object') return '';
  return String(value).trim();
}

const searchDate = new Date().toISOString().slice(0, 10);
const out = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const j = items[i].json;
  const records = toArray(j.records);

  for (let r = 0; r < records.length; r++) {
    const rec = records[r] || {};

    const phones = toArray(rec.PHONES && rec.PHONES.PHONE).map(safe).filter(Boolean);
    const emails = toArray(rec.EMAILS && rec.EMAILS.EMAIL).map(safe).filter(Boolean);
    const addresses = toArray(rec.ADDRESSES && rec.ADDRESSES.ADDRESS)
      .map((a) => ({
        street: safe(a && a.STREET),
        city: safe(a && a.CITY),
        county: safe(a && a.COUNTY),
        state: safe(a && a.STATE),
        zip: safe(a && a.ZIP),
      }))
      .filter((a) => a.street || a.city || a.zip);

    const current = addresses[0] || { street: '', city: '', county: '', state: '', zip: '' };

    out.push({
      json: {
        SEARCH_ID: safe(j.search_id),
        SEARCHED_NAME: safe(j.searched_name),
        SEARCHED_CITY: safe(j.searched_city),
        SEARCHED_STATE: safe(j.searched_state),
        SEARCHED_PHONE: safe(j.searched_phone),
        SEARCHED_EMAIL: safe(j.searched_email),
        RECORD_RANK: r + 1,
        FNAME: safe(rec.FNAME),
        MNAME: safe(rec.MNAME),
        LNAME: safe(rec.LNAME),
        BNAME: safe(rec.BNAME),
        PHONE: phones[0] || '',
        PHONE_COUNT: phones.length,
        PHONES_ALL: phones.join(' | '),
        EMAIL: emails[0] || '',
        EMAIL_COUNT: emails.length,
        EMAILS_ALL: emails.join(' | '),
        STREET: current.street,
        CITY: current.city,
        COUNTY: current.county,
        STATE: current.state,
        ZIP: current.zip,
        ADDRESS_COUNT: addresses.length,
        DOB: safe(rec.DOB),
        AGE: safe(rec.AGE),
        SEARCH_DATE: searchDate,
        _addresses: addresses,
      },
      pairedItem: { item: i },
    });
  }
}

return out;

// MATCH_SCORE      - does this record match what was actually searched?
// COMPLETENESS_SCORE - how usable is the contact record on its own?
function norm(value) {
  return String(value === null || value === undefined ? '' : value)
    .toUpperCase().replace(/[^A-Z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
}

function digits(value) {
  return String(value === null || value === undefined ? '' : value).replace(/[^0-9]/g, '');
}

function part(searched, found) {
  if (!searched || !found) return 0;
  if (searched === found) return 1;
  if (found.startsWith(searched) || searched.startsWith(found)) return 0.5;
  return 0;
}

const out = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const row = Object.assign({}, items[i].json);

  // --- match score ---
  const searchedPhone = digits(row.SEARCHED_PHONE);
  const searchedEmail = norm(row.SEARCHED_EMAIL);
  const searchedName = norm(row.SEARCHED_NAME).split(' ').filter(Boolean);

  let score = 0;
  if (searchedName.length > 0) {
    const searchedFirst = searchedName[0];
    const searchedLast = searchedName.length > 1 ? searchedName[searchedName.length - 1] : '';
    score += 35 * part(searchedFirst, norm(row.FNAME));
    score += 45 * part(searchedLast, norm(row.LNAME));
    if (norm(row.SEARCHED_STATE) && norm(row.SEARCHED_STATE) === norm(row.STATE)) score += 20;
  } else if (searchedPhone) {
    // reverse phone lookup: did the number we searched come back on the record?
    const found = String(row.PHONES_ALL || '').split('|').map(digits).filter(Boolean);
    score = found.indexOf(searchedPhone) !== -1 ? 100 : 60;
  } else if (searchedEmail) {
    const found = String(row.EMAILS_ALL || '').split('|').map(norm).filter(Boolean);
    score = found.indexOf(searchedEmail) !== -1 ? 100 : 60;
  } else {
    score = 60;
  }
  row.MATCH_SCORE = Math.round(score);

  // --- completeness score ---
  let complete = 0;
  if (row.FNAME || row.LNAME || row.BNAME) complete += 20;
  if (row.STREET) complete += 25;
  if (row.CITY && row.STATE) complete += 10;
  if (row.ZIP) complete += 5;
  if (Number(row.PHONE_COUNT) > 0) complete += 20;
  if (Number(row.EMAIL_COUNT) > 0) complete += 20;
  row.COMPLETENESS_SCORE = complete;

  if (complete >= 85) row.CONTACT_GRADE = 'A';
  else if (complete >= 70) row.CONTACT_GRADE = 'B';
  else if (complete >= 50) row.CONTACT_GRADE = 'C';
  else row.CONTACT_GRADE = 'D';

  const flags = [];
  if (Number(row.PHONE_COUNT) === 0) flags.push('NO_PHONE');
  if (Number(row.EMAIL_COUNT) === 0) flags.push('NO_EMAIL');
  if (Number(row.ADDRESS_COUNT) === 0) flags.push('NO_ADDRESS');
  if (Number(row.ADDRESS_COUNT) >= 4) flags.push('MANY_ADDRESSES');
  if (row.BNAME) flags.push('BUSINESS_RECORD');
  if (row.MATCH_SCORE < 70) flags.push('WEAK_MATCH');
  row.FLAGS = flags.join(', ');

  out.push({ json: row, pairedItem: { item: i } });
}

return out;

// One row per address on the record, current first.
const out = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const row = items[i].json;
  const addresses = Array.isArray(row._addresses) ? row._addresses : [];
  const fullName = [row.FNAME, row.MNAME, row.LNAME].filter(Boolean).join(' ') || row.BNAME || '';

  for (let a = 0; a < addresses.length; a++) {
    out.push({
      json: {
        SEARCH_ID: row.SEARCH_ID,
        RECORD_RANK: row.RECORD_RANK,
        FULL_NAME: fullName,
        ADDRESS_RANK: a + 1,
        IS_CURRENT: a === 0 ? 'Yes' : 'No',
        STREET: addresses[a].street,
        CITY: addresses[a].city,
        COUNTY: addresses[a].county,
        STATE: addresses[a].state,
        ZIP: addresses[a].zip,
        SEARCH_DATE: row.SEARCH_DATE,
      },
      pairedItem: { item: i },
    });
  }
}

return out;

// One row per search, however many records came back.
const groups = {};
const order = [];

for (const item of $input.all()) {
  const j = item.json;
  const key = String(j.SEARCH_ID || '');

  if (!groups[key]) {
    order.push(key);
    groups[key] = {
      SEARCH_ID: key,
      SEARCHED_NAME: j.SEARCHED_NAME || '',
      SEARCHED_CITY: j.SEARCHED_CITY || '',
      SEARCHED_STATE: j.SEARCHED_STATE || '',
      RECORDS_FOUND: 0,
      BEST_MATCH_NAME: '',
      BEST_MATCH_SCORE: -1,
      BEST_COMPLETENESS: 0,
      CONTACT_GRADE: 'D',
      TOTAL_PHONES: 0,
      TOTAL_EMAILS: 0,
      TOTAL_ADDRESSES: 0,
      FLAGS: {},
    };
  }

  const g = groups[key];
  g.RECORDS_FOUND++;
  g.TOTAL_PHONES += Number(j.PHONE_COUNT) || 0;
  g.TOTAL_EMAILS += Number(j.EMAIL_COUNT) || 0;
  g.TOTAL_ADDRESSES += Number(j.ADDRESS_COUNT) || 0;

  const score = Number(j.MATCH_SCORE) || 0;
  if (score > g.BEST_MATCH_SCORE) {
    g.BEST_MATCH_SCORE = score;
    g.BEST_MATCH_NAME = [j.FNAME, j.MNAME, j.LNAME].filter(Boolean).join(' ') || j.BNAME || '';
    g.BEST_COMPLETENESS = Number(j.COMPLETENESS_SCORE) || 0;
    g.CONTACT_GRADE = j.CONTACT_GRADE || 'D';
  }

  String(j.FLAGS || '').split(',').map((f) => f.trim()).filter(Boolean)
    .forEach((f) => { g.FLAGS[f] = true; });
}

const summaryDate = new Date().toISOString().slice(0, 10);

return order.map((key) => {
  const g = groups[key];
  return {
    json: {
      SEARCH_ID: g.SEARCH_ID,
      SEARCHED_NAME: g.SEARCHED_NAME,
      SEARCHED_CITY: g.SEARCHED_CITY,
      SEARCHED_STATE: g.SEARCHED_STATE,
      RECORDS_FOUND: g.RECORDS_FOUND,
      BEST_MATCH_NAME: g.BEST_MATCH_NAME,
      BEST_MATCH_SCORE: g.BEST_MATCH_SCORE < 0 ? 0 : g.BEST_MATCH_SCORE,
      BEST_COMPLETENESS: g.BEST_COMPLETENESS,
      CONTACT_GRADE: g.CONTACT_GRADE,
      TOTAL_PHONES: g.TOTAL_PHONES,
      TOTAL_EMAILS: g.TOTAL_EMAILS,
      TOTAL_ADDRESSES: g.TOTAL_ADDRESSES,
      FLAGS: Object.keys(g.FLAGS).join(', '),
      SUMMARY_DATE: summaryDate,
    },
  };
});
